"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [403, 191, 1222, 238], \"page_id\": 138}], \"content\": \"INTRODUCTION: Oil Spill Liability Trust Fund\", \"description\": null, \"id\": 1, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [137, 250, 805, 443], \"page_id\": 138}], \"content\": \"The Oil Spill Liability Trust Fund was established on the books of the Treasury by section 8033 of the Omnibus Budget Reconciliation Act of 1986 (Public Law 99-509). It was made effective on January 1, 1990, by section 7811(m)(3) of the Omnibus Budget Reconciliation Act of 1989 (Public Law 101-239) and amended by section 9001 of the Oil Pollution Act of 1990 (Public Law 101-380).\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [135, 448, 801, 589], \"page_id\": 138}], \"content\": \"Certain amounts were transferred from other funds and were appropriated to the Oil Spill Liability Trust Fund as provided by 26 United States Code 9509(b). Certain paid penalties and amounts recovered for removal costs and damages are also appropriated to the fund.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [827, 250, 1495, 361], \"page_id\": 138}], \"content\": \"Amounts in the fund are available for oil spill cleanup costs and certain other related purposes as provided by appropriations acts or section 6002(b) of the Oil Pollution Act of 1990 (Public Law 101-380).\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [825, 361, 1495, 469], \"page_id\": 138}], \"content\": \"When the provisions of 26 United States Code 9602(b) are met, amounts available in the fund exceeding outlay requirements are invested in public debt securities. Interest is credited to the fund.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [820, 471, 1499, 620], \"page_id\": 138}], \"content\": \"Annual reports to Congress, required by 26 United States Code 9602(a), are submitted by the Secretary of the Treasury. These reports are required to cover the financial condition and results of operations of the fund during the past fiscal year and those expected during the next 5 fiscal years.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [484, 646, 1153, 714], \"page_id\": 138}], \"content\": \"TABLE TF-21.\\u2014Oil Spill Liability Trust Fund Results of Operations, Fiscal 2000\", \"description\": null, \"id\": 7, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [681, 738, 949, 771], \"page_id\": 138}], \"content\": \"[Source: Bureau of the Public Debt]\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [133, 773, 1501, 1436], \"page_id\": 138}], \"content\": \"<table><tr><td>Balance Oct. 1, 1999</td><td>$1,027,784,314</td></tr><tr><td>Revenue:</td><td></td></tr><tr><td>Tax on crude oil/petroleum products.</td><td>5,000</td></tr><tr><td>Trans-Alaska Pipeline liability fund deposit.</td><td>181,846,967</td></tr><tr><td>Cost recoveries</td><td>6,645,108</td></tr><tr><td>Fines and penalties</td><td>33,461,537</td></tr><tr><td>Total revenue before interest</td><td>221,958,612</td></tr><tr><td>Interest on investment revenue</td><td>62,131,373</td></tr><tr><td>Realized loss</td><td>-77,896</td></tr><tr><td>Total investment revenue</td><td>62,053,477</td></tr><tr><td>Total revenue</td><td>284,012,089</td></tr><tr><td>Expenditures:</td><td></td></tr><tr><td>Treasury administrative expense - BPD</td><td>2,141</td></tr><tr><td>Non-expenditure transfers:</td><td></td></tr><tr><td>Transfer to Denali commission</td><td>5,475,967</td></tr><tr><td>Transfer to Interior</td><td>6,118,000</td></tr><tr><td>Transfer to EPA</td><td>14,974,400</td></tr><tr><td>Transfer to DOT</td><td>5,479,000</td></tr><tr><td>Transfer to U.S. Coast Guard</td><td>285,778,840</td></tr><tr><td>Total Nonexpenditures transfers</td><td>317,826,207</td></tr><tr><td>Total expenditure/non-expenditure transfers</td><td>317,828,348</td></tr><tr><td>Balance Sept. 30, 2000</td><td>$993,968,055</td></tr></table>\", \"description\": null, \"id\": 9, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [359, 1490, 1279, 1565], \"page_id\": 138}], \"content\": \"TABLE TF-21.\\u2014Oil Spill Liability Trust Fund Expected Condition and Results of Operations, Fiscal 2001-2005\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [588, 1593, 1033, 1617], \"page_id\": 138}], \"content\": \"(In millions of dollars. Source: Department of Transportation)\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [135, 1622, 1497, 1888], \"page_id\": 138}], \"content\": \"<table><tr><th></th><th>2001</th><th>2002</th><th>2003</th><th>2004</th><th>2005</th></tr><tr><td>Balance, Oct. 1</td><td>1,164</td><td>1,129</td><td>981</td><td>839</td><td>685</td></tr><tr><td>Estimated receipts</td><td>131</td><td>100</td><td>102</td><td>93</td><td>85</td></tr><tr><td>Estimated expenses</td><td>166</td><td>248</td><td>244</td><td>247</td><td>255</td></tr><tr><td>Balance Sept. 30</td><td>1,129</td><td>981</td><td>839</td><td>685</td><td>515</td></tr></table>\", \"description\": null, \"id\": 12, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [672, 80, 958, 123], \"page_id\": 139}], \"content\": \"TECHNICAL PAPERS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1441, 80, 1494, 123], \"page_id\": 139}], \"content\": \"141\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [608, 196, 1020, 250], \"page_id\": 139}], \"content\": \"Research Paper Series\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [242, 304, 1401, 349], \"page_id\": 139}], \"content\": \"Available through the Office of the Assistant Secretary for Economic Policy\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [138, 384, 1366, 429], \"page_id\": 139}], \"content\": \